/**
 * Iconos SVG inline: sin librerías externas, heredan color con currentColor
 * y tamaño con la prop `size`.
 */
type Props = { size?: number; className?: string };

/**
 * Como {@link base}, pero con el recuadro que traiga el dibujo.
 *
 * Los iconos del directo vienen de fuera y cada uno trae el suyo, recortado a
 * su contenido. Forzarlos a 0 0 24 24 los descolocaría.
 */
const conCaja = (viewBox: string, size: number, className?: string) => ({
  ...base(size, className),
  viewBox,
});

const base = (size: number, className?: string) => ({
  width: size,
  height: size,
  viewBox: "0 0 24 24",
  className,
  "aria-hidden": true as const,
  focusable: "false" as const,
});

