/**
 * Tiro libre: el balón y la trayectoria con efecto.
 *
 * Ya no tiene botón, pero los partidos retransmitidos antes llevan ese evento
 * guardado y su cronología tiene que seguir pintándose.
 */
export function IconoTiroLibre({ size = 20, className }: Props) {
  return (
    <svg {...base(size, className)} fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
      <circle cx="6" cy="18" r="2.8" />
      <path d="M7.4 15.2C11 6.5 18 6.5 20.5 11.5" strokeDasharray="3 2.6" />
      <path d="M17.6 11.2l3 .4.6-3" />
    </svg>
  );
}

/** Tarjeta: la única que lleva su color, porque el color ES la información. */
export function IconoTarjeta({
  color,
  size = 20,
  className,
}: Props & { color: "amarilla" | "roja" }) {
  return (
    <svg {...conCaja("0 0 24 24", size, className)} fill="none">
      <rect
        x="6.5"
        y="3"
        width="11"
        height="18"
        rx="2.2"
        transform="rotate(9 12 12)"
        fill={color === "amarilla" ? "var(--color-amarilla-tarjeta)" : "var(--color-roja-tarjeta)"}
      />
    </svg>
  );
}

/**
 * Comentario: el bocadillo.
 *
 * De trazo y no macizo a propósito: relleno pesaría más que ningún otro icono, y
 * es el que más veces sale en una retransmisión.
 */
export function IconoComentario({ size = 20, className }: Props) {
  return (
    <svg {...conCaja("0 0 24 24", size, className)} fill="none" stroke="currentColor" strokeWidth="1.9" strokeLinejoin="round">
      <path d="M3.9 3.4h16.2a1.7 1.7 0 0 1 1.7 1.7v9.7a1.7 1.7 0 0 1-1.7 1.7h-9L5.1 21v-4.5H3.9a1.7 1.7 0 0 1-1.7-1.7V5.1a1.7 1.7 0 0 1 1.7-1.7z" />
    </svg>
  );
}

/** Lápiz: corregir algo ya escrito. */
export function IconoLapiz({ size = 16, className }: Props) {
  return (
    <svg {...base(size, className)} fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
      <path d="M4 20h4l10-10a2.8 2.8 0 0 0-4-4L4 16z" />
      <path d="M13.5 6.5l4 4" />
    </svg>
  );
}
